func (this *Derive) HandleTicker(client any, message map[string]any) any {
	//
	//     {
	//         "method": "subscription",
	//         "params": {
	//             "channel": "ticker_slim.BTC-PERP.100",
	//             "data": {
	//                 "timestamp": 1790879819285,
	//                 "instrument_ticker": {
	//                     "t": 1790879819268,
	//                     "A": "0.278",
	//                     "a": "84214.6",
	//                     "B": "0.213",
	//                     "b": "84205.4",
	//                     "f": "0.000012500",
	//                     "option_pricing": null,
	//                     "I": "84210.9",
	//                     "M": "84210.2",
	//                     "stats": {
	//                         "c": "16.41",
	//                         "v": "1377350.271",
	//                         "pr": "1377095.872",
	//                         "n": 98,
	//                         "oi": "0",
	//                         "h": "84282",
	//                         "l": "83661.8",
	//                         "p": "0"
	//                     },
	//                     "minp": "82526.1",
	//                     "maxp": "85894.9"
	//                 }
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var rawData map[string]any = ccxt.SafeMapTyped(params, "data")
	var data map[string]any = this.SafeDictMap(rawData, "instrument_ticker", map[string]any{})
	var topic *string = this.SafeString(params, "channel", "")
	// the slim payload does not carry the instrument name, so the symbol is recovered from the channel: ticker_slim.BTC-PERP.100
	var parts []string = strings.Split(*topic, ".")
	var marketId *string = this.SafeString(parts, 1)
	var market map[string]any = this.SafeMarket(marketId)
	var ticker map[string]any = ccxt.TickerToMap(this.ParseTicker(data, market))
	var tickerSymbol *string = ccxt.SafeStringPtr(ticker["symbol"])
	if tickerSymbol != nil {
		this.Tickers.Store(tickerSymbol, ticker)
		var bidAsk map[string]any = ccxt.TickerToMap(this.SafeTicker(map[string]any{
			"symbol":    tickerSymbol,
			"timestamp": this.SafeInteger(ticker, "timestamp"),
			"datetime":  this.SafeString(ticker, "datetime"),
			"bid":       this.SafeNumber(ticker, "bid"),
			"bidVolume": this.SafeNumber(ticker, "bidVolume"),
			"ask":       this.SafeNumber(ticker, "ask"),
			"askVolume": this.SafeNumber(ticker, "askVolume"),
			"info":      data,
		}, market))
		this.Bidsasks.Store(tickerSymbol, bidAsk)
		client.(ccxt.ClientInterface).Resolve(bidAsk, "bidask:"+*tickerSymbol)
	}
	client.(ccxt.ClientInterface).Resolve(ticker, topic)
	return message
}

