func (this *Derive) HandleOrder(client any, message map[string]any) {
	//
	// {
	//     method: 'subscription',
	//     params: {
	//         channel: '130837.orders',
	//         data: [
	//             {
	//                 subaccount_id: 130837,
	//                 order_id: '1f44c564-5658-4b69-b8c4-4019924207d5',
	//                 instrument_name: 'BTC-PERP',
	//                 direction: 'buy',
	//                 label: 'test1234',
	//                 quote_id: null,
	//                 creation_timestamp: 1738578974146,
	//                 last_update_timestamp: 1738578974146,
	//                 limit_price: '10000',
	//                 amount: '0.01',
	//                 filled_amount: '0',
	//                 average_price: '0',
	//                 order_fee: '0',
	//                 order_type: 'limit',
	//                 time_in_force: 'post_only',
	//                 order_status: 'untriggered',
	//                 max_fee: '219',
	//                 signature_expiry_sec: 1746354973,
	//                 nonce: 1738578973570,
	//                 signer: '0x30CB7B06AdD6749BbE146A6827502B8f2a79269A',
	//                 signature: '0xc6927095f74a0d3b1aeef8c0579d120056530479f806e9d2e6616df742a8934c69046361beae833b32b25c0145e318438d7d1624bb835add956f63aa37192f571c',
	//                 cancel_reason: '',
	//                 mmp: false,
	//                 is_transfer: false,
	//                 replaced_order_id: null,
	//                 trigger_type: 'stoploss',
	//                 trigger_price_type: 'mark',
	//                 trigger_price: '102800',
	//                 trigger_reject_message: null
	//             }
	//         ]
	//     }
	// }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var topic *string = this.SafeString(params, "channel")
	var rawOrders []any = ccxt.SafeListTyped(params, "data")
	for i := 0; i < len(rawOrders); i++ {
		var data any = func() any {
			if i >= 0 && i < len(rawOrders) {
				return ccxt.DerefScalar(rawOrders[i])
			}
			return nil
		}()
		var parsed map[string]any = ccxt.OrderToMap(this.ParseOrder(data))
		var symbol *string = this.SafeString(parsed, "symbol")
		var orderId *string = this.SafeString(parsed, "id")
		if symbol != nil {
			if this.Orders == nil {
				var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
				this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
			}
			var cachedOrders any = this.Orders
			var orders map[string]any = ccxt.SafeMapTyped(cachedOrders.(*ccxt.ArrayCache).Hashmap, symbol)
			var order any = func() any {
				if orderId == nil {
					return nil
				}
				return this.SafeDict(orders, orderId)
			}()
			if order != nil {
				var fee any = this.SafeDict(order, "fee")
				if fee != nil {
					ccxt.AddElementToObject(parsed, "fee", fee)
				}
				var fees any = this.SafeList(order, "fees")
				if fees != nil {
					ccxt.AddElementToObject(parsed, "fees", fees)
				}
				ccxt.AddElementToObject(parsed, "trades", this.SafeList(order, "trades"))
				parsed["timestamp"] = this.SafeInteger(order, "timestamp")
				parsed["datetime"] = this.SafeString(order, "datetime")
			}
			cachedOrders.(ccxt.Appender).Append(parsed)
			if topic != nil {
				var messageHashSymbol string = *topic + ":" + *symbol
				client.(ccxt.ClientInterface).Resolve(this.Orders, messageHashSymbol)
			}
		}
	}
	client.(ccxt.ClientInterface).Resolve(this.Orders, topic)
}

